import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/atlas/overview.md","filePath":"en/projects/atlas/overview.md","lastUpdated":1793113714000}'),r={name:"en/projects/atlas/overview.md"};function o(d,e,c,l,s,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>ATLAS is developed as a modular TypeScript monorepo.</p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>core</code></td><td>Central contracts and foundational types</td></tr><tr><td><code>foundation</code></td><td>Shared infrastructure and general building blocks</td></tr><tr><td><code>runtime</code></td><td>Runtime environment, services and service container</td></tr><tr><td><code>renderer</code></td><td>Presentation layer and renderer abstractions</td></tr><tr><td><code>homeassistant</code></td><td>Integration package for Home Assistant workflows</td></tr><tr><td><code>theme</code></td><td>Shared theme and design foundations</td></tr><tr><td><code>devtools</code></td><td>Diagnostics and development tools</td></tr><tr><td><code>kernel</code></td><td>Module contracts, service container and infrastructure</td></tr><tr><td><code>workspace</code></td><td>Workspace readiness contracts</td></tr><tr><td><code>file-studio</code></td><td>Internal File Studio contracts and Runtime adapter; the installable web plugin remains external</td></tr><tr><td><code>notifyarchive</code></td><td>Internal notification archive contracts</td></tr></tbody></table><h2 id="architecture-principles" tabindex="-1">Architecture Principles <a class="header-anchor" href="#architecture-principles" aria-label="Permalink to &quot;Architecture Principles&quot;">​</a></h2><p>ATLAS follows a few fixed principles:</p><ul><li>clear separation between contracts and implementations</li><li>small, replaceable modules</li><li>testable components</li><li>dependencies through defined interfaces</li><li>reference implementations for central services</li><li>long-term plugin extensibility</li></ul><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><p>The event layer includes:</p><ul><li><code>Event</code></li><li><code>EventBus</code></li><li><code>Handler</code></li><li><code>Subscription</code></li><li><code>Filter</code></li><li><code>Publisher</code></li><li><code>Subscriber</code></li></ul><p><code>DefaultEventBus</code> is the reference implementation.</p><h2 id="services-and-dependency-injection" tabindex="-1">Services and Dependency Injection <a class="header-anchor" href="#services-and-dependency-injection" aria-label="Permalink to &quot;Services and Dependency Injection&quot;">​</a></h2><p>The Runtime Foundation contains the groundwork for:</p><ul><li>service descriptors</li><li>service registration</li><li>dependency injection</li><li>service containers</li><li>controlled dependency resolution</li></ul><h2 id="planned-usage" tabindex="-1">Planned Usage <a class="header-anchor" href="#planned-usage" aria-label="Permalink to &quot;Planned Usage&quot;">​</a></h2><p>ATLAS is intended to support:</p><ul><li>Home Assistant tools</li><li>dashboard components</li><li>diagnostics applications</li><li>plugin-based desktop or web applications</li><li>the planned <strong>Lovelace UV Card</strong></li></ul><p>The contracts are still in development; this architecture does not promise a stable plugin API. See <a href="/en/projects/atlas/development-status">Development Status</a>.</p>',18)])])}const m=t(r,[["render",o]]);export{h as __pageData,m as default};
